def preserve_legacy_notes(apps, schema_editor):
    Old = apps.get_model('core', 'MistakeNote')
    New = apps.get_model('core', 'PersonalNote')
    alias = schema_editor.connection.alias
    for old in Old.objects.using(alias).iterator():
        body = (f'Problem: https://codeforces.com/problemset/problem/{old.contest_id}/{old.problem_index}\n\n'
                f'Mistake:\n{old.mistake}\n\nLesson:\n{old.lesson}\n\nTopics: {old.topics}\n'
                f'Revision requested: {old.needs_revision}')
        note, created = New.objects.using(alias).get_or_create(legacy_note_id=old.pk, defaults={
            'owner_id': old.user_id, 'title': f'{old.contest_id}{old.problem_index} {old.problem_name}'[:200],
            'content': body, 'topic': old.topics})
        if created:
            New.objects.using(alias).filter(pk=note.pk).update(created_at=old.updated_at, updated_at=old.updated_at)


